import { Controller, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 범위는 조회자의 menu_permission 중 가장 넓은 view_scope로 정한다 (메뉴를 특정하는 근거가 없음).
// 가정: 개인정보 열람 이력의 대상 정보 구분은 '인사정보', 접근 유형은 '조회'로 기록한다.
const ACTIVITY_TYPES = ['전자결재', '게시판'];
const LOG_INFO_TYPE = '인사정보';
const LOG_ACCESS_TYPE = '조회';
const SCOPE_RANK: Record<string, number> = { '개인': 1, '부서': 2, '전체': 3 };

@Controller('api/v1')
export class FnSfr03902Controller {
  @Get('/employees/:employeeId/activities')
  async listEmployeeActivities(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const employeeId = req.params['employeeId'];
    if (!/^[0-9]+$/.test(employeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조직원 ID가 올바르지 않습니다.');
    }
    const activityTypeRaw = query['activityType'];
    let activityType: string | null = null;
    if (activityTypeRaw !== undefined && activityTypeRaw !== null && activityTypeRaw !== '') {
      activityType = String(activityTypeRaw);
      if (!ACTIVITY_TYPES.includes(activityType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '활동 구분은 전자결재 또는 게시판이어야 합니다.');
      }
    }
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);

    return transaction(async (db) => {
      const scopes = await db.query(
        `SELECT view_scope AS "viewScope"
           FROM menu_permission
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      let rank = 0;
      for (const s of scopes) {
        const r = SCOPE_RANK[String((s as any).viewScope)] ?? 0;
        if (r > rank) {
          rank = r;
        }
      }
      const viewers = await db.query(
        `SELECT department_id AS "departmentId"
           FROM employee
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      const targets = await db.query(
        `SELECT department_id AS "departmentId"
           FROM employee
          WHERE employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (targets.length === 0 || viewers.length === 0 || rank === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조회할 수 있는 조직원이 없습니다.');
      }
      const viewerDept = Number((viewers[0] as any).departmentId);
      const targetDept = Number((targets[0] as any).departmentId);
      const isSelf = String(employeeId) === String(user.id);
      const inScope = rank === 3 || (rank === 2 && viewerDept === targetDept) || isSelf;
      if (!inScope) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조회할 수 있는 조직원이 없습니다.');
      }
      const sameDept = viewerDept === targetDept;

      await db.execute(
        `INSERT INTO personal_info_access_log
           (employee_id, target_employee_id, target_info_type, access_type, accessed_at, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:employeeId AS bigint), :infoType, :accessType, now(), now(), now())`,
        { userId: user.id, employeeId, infoType: LOG_INFO_TYPE, accessType: LOG_ACCESS_TYPE },
      );

      const withClause = `WITH acts AS (
          SELECT '전자결재' AS "activityType", d.title AS "title", d.created_at AS "activityAt"
            FROM approval_document d
           WHERE d.drafter_id = CAST(:employeeId AS bigint)
          UNION ALL
          SELECT '게시판' AS "activityType", p.title AS "title", p.created_at AS "activityAt"
            FROM board_post p
           WHERE p.author_id = CAST(:employeeId AS bigint)
             AND (p.visibility_scope = '전체'
                  OR (p.visibility_scope = '부서' AND CAST(:sameDept AS boolean))
                  OR (p.visibility_scope = '개인' AND CAST(:isSelf AS boolean)))
        )`;
      const params = { employeeId, sameDept, isSelf, activityType };

      const items = await db.query(
        `${withClause}
         SELECT "activityType", "title", "activityAt"
           FROM acts
          WHERE (CAST(:activityType AS text) IS NULL OR "activityType" = CAST(:activityType AS text))
          ORDER BY "activityAt" DESC
          LIMIT :size OFFSET :offset`,
        { ...params, size, offset: page * size },
      );
      const counts = await db.query(
        `${withClause}
         SELECT COUNT(*) AS "total"
           FROM acts
          WHERE (CAST(:activityType AS text) IS NULL OR "activityType" = CAST(:activityType AS text))`,
        params,
      );
      const total = Number((counts[0] as any).total);
      return { items, page, size, total };
    });
  }
}

