import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateText,
  Field,
  Filters,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  TextInput,
  Select,
  ErrorText,
  call,
  useData,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const ACTIVITY_OPTIONS: [string, string][] = [
  ['전자결재', '전자결재'],
  ['게시판', '게시판'],
];

function Activities({ role, employee, onBack }: { role: string; employee: Row; onBack: () => void }) {
  const [activityType, setActivityType] = useState('');
  const [page, setPage] = useState(0);
  const { data, error, loading, reload } = useData<Page>(
    () =>
      call<Page>('GET', `/employees/${employee['employeeId']}/activities`, role, undefined, {
        activityType,
        page,
        size: 20,
      }),
    [employee['employeeId'], activityType, page],
  );
  return (
    <div className="doc">
      <button className="ghost" onClick={onBack}>
        조직원 목록으로 돌아가기
      </button>
      <section className="box">
        <h2>프로필</h2>
        <Pairs
          items={[
            ['사번', String(employee['employeeNo'] ?? '')],
            ['임직원명', String(employee['name'] ?? '')],
            ['주부서', <RefName table="department" role={role} value={employee['departmentId']} />],
            ['재직 구분', <Badge value={employee['employmentStatus']} />],
            ['이메일', String(employee['email'] ?? '')],
            ['휴대전화번호', String(employee['mobilePhone'] ?? '')],
          ]}
        />
      </section>
      <section className="box">
        <h2>업무활동 내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            reload();
          }}
          onReset={() => {
            setActivityType('');
            setPage(0);
          }}
        >
          <Field label="활동 구분">
            <Select
              value={activityType}
              onChange={(v) => {
                setActivityType(v);
                setPage(0);
              }}
              options={ACTIVITY_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'activityType', label: '활동 유형', render: (r) => <Badge value={r['activityType']} /> },
            { key: 'title', label: '문서·게시물 제목' },
            { key: 'activityAt', label: '활동 일시', render: (r) => <DateText value={r['activityAt']} time /> },
          ]}
          rows={loading ? [] : data?.items ?? []}
          empty="조회할 수 있는 업무활동 내역이 없습니다."
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}

export default function FnSfr03902Page({ role, notify }: PageProps) {
  const [name, setName] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/employees', role, undefined, { departmentId, page, size: 20 }),
    [departmentId, page],
  );
  if (selected) {
    return <Activities role={role} employee={selected} onBack={() => setSelected(null)} />;
  }
  const keyword = name.trim();
  const rows = (data?.items ?? []).filter((r) => keyword === '' || String(r['name'] ?? '').includes(keyword));
  return (
    <div className="doc">
      <section className="box">
        <h2>조직원 검색</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            reload();
          }}
          onReset={() => {
            setName('');
            setDepartmentId('');
            setPage(0);
          }}
        >
          <Field label="임직원명">
            <TextInput value={name} onChange={setName} placeholder="이름을 입력하세요" />
          </Field>
          <Field label="주부서">
            <LookupSelect
              table="department"
              role={role}
              value={departmentId}
              onChange={(v) => {
                setDepartmentId(v);
                setPage(0);
              }}
              placeholder="전체"
            />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={rows.length} />
        <DataTable
          columns={[
            { key: 'employeeNo', label: '사번' },
            { key: 'name', label: '임직원명' },
            { key: 'departmentId', label: '주부서', render: (r) => <RefName table="department" role={role} value={r['departmentId']} /> },
            { key: 'employmentStatus', label: '재직 구분', render: (r) => <Badge value={r['employmentStatus']} /> },
          ]}
          rows={loading ? [] : rows}
          onRowClick={(r) => {
            setSelected(r);
            notify('조직원을 선택했습니다.');
          }}
          empty="검색 결과가 없습니다. 검색어나 부서를 바꿔 다시 조회해 주세요."
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
    </div>
  );
}
